public class SR {
 public String keys(SObject row) {
  List<String> xs=new List<String>(row.getPopulatedFieldsAsMap().keySet());
  xs.sort(); return String.join(xs,'|');
 }
 public String childNames(List<Contact> rows) {
  List<String> xs=new List<String>();
  for(Contact row:rows) xs.add(row.LastName);
  return String.join(xs,'|');
 }
 public String names(List<SObject> rows,String field) {
  List<String> xs=new List<String>();
  for(SObject row:rows) xs.add(String.valueOf(row.get(field)));
  return String.join(xs,'|');
 }
 public String kind(SObject row) {
  return row==null?'null':String.valueOf(row.getSObjectType());
 }
}

